CREATE TABLE pending_reviewed (user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, item_key VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (user_id,item_key), CONSTRAINT pending_reviewed_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci